INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp6', 85968, 94200, 'The run-up to the board meeting is optimistic for the ingest rewrite given waiting on legal, but it is not impossible.', 21, 0, 0, 0.942);
