INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp4', 102397, 107485, 'I will keep this quick, I know we are tight on time.', 12, 0, 0, 0.947);
