INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp5', 131257, 150761, 'September closed Friday. ARR is four point eight two million, which is up eighty-one thousand on August. Net revenue retention is a hundred and twelve percent. Gross churn came in at one point nine, so slightly better than the two point two we had planned for.', 46, 0, 0, 0.951);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 151003, 152571, 'And the pipeline number?', 4, 0, 0, 0.958);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp5', 152899, 160955, 'Two point one million in qualified pipeline for Q4. That is the number I would be careful with, actually.', 19, 0, 0, 0.95);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp3', 161571, 162323, 'Careful how?', 2, 0, 0, 0.951);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp5', 162935, 178199, 'Because about three hundred and forty thousand of that is Halcyon, and Halcyon is not signed. If we are reporting pipeline to the board with Halcyon in it and Halcyon slips to November, the number moves.', 36, 0, 0, 0.947);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp3', 178652, 188052, 'That is fair, but Halcyon is in late-stage legal. It is not a hope-and-a-prayer deal. I would rather over-communicate the risk than quietly drop it.', 25, 0, 0, 0.981);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 188609, 194097, 'So what are we actually agreeing? Tom, do you want it in or out?', 14, 0, 0, 0.982);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp5', 194514, 202146, 'In, but flagged. Separate line in the board deck that says committed versus best-case. Then nobody is surprised.', 18, 0, 0, 0.953);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 202489, 213857, 'Okay. Marcus, can you and Tom agree the wording before Friday and just send it to me? I do not want to spend board time on a definitions argument.', 29, 0, 0, 0.966);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp3', 214291, 216171, 'Yes, we will sort it.', 5, 0, 0, 0.986);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp5', 216671, 227695, 'One more thing. New logo count is six for the quarter against a target of nine. That is the number that worries me more than churn.', 26, 0, 0, 0.981);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp6', 228114, 237914, 'Can I add context there? Two of the six are expansions, not logos. So the underlying new-business number is four. I would not sugarcoat it.', 25, 0, 0, 0.947);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 238254, 249230, 'Right. Okay, that is genuinely useful. Let us not move the target mid-quarter, but let us talk about what we do about it in the Q4 planning session.', 28, 0, 0, 0.971);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp5', 249754, 256114, 'That is the third time this has come up this month, which tells me something.', 15, 0, 0, 0.961);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 255653, 262421, 'I am less worried about the untested rollback path than about nobody owning it, if I am honest.', 18, 1, 0, 0.978);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp7', 262917, 269853, 'onboarding v3 needs a decision, not another conversation - pairing someone senior on it is good enough.', 17, 0, 0, 0.968);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 270191, 277247, 'Nothing changed on the Halcyon integration since last week, which is itself a signal about waiting on legal.', 18, 0, 0, 0.97);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp6', 277832, 282144, 'I am happy to own that if nobody else wants it.', 11, 0, 0, 0.931);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp7', 283341, 288237, 'Sorry, can you say that again? You cut out for a second.', 12, 0, 0, 0.976);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp3', 287959, 292095, 'Yep, that matches what I saw in the dashboard this morning.', 11, 1, 0, 0.946);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 292445, 296205, 'I think we are agreeing with each other here, actually.', 10, 0, 0, 0.934);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp5', 296629, 300869, 'My concern is less the what and more the when.', 10, 0, 0, 0.987);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp4', 301246, 308030, 'Quick flag - Aisha Bello is out next week, so anything needing them has to move.', 16, 0, 0, 0.981);
