INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp3', 711655, 724815, 'Halcyon. One hundred and eighty thousand ACV, three-year term, they want to start in November. The blocker is not commercial, it is their security review. Dev Patel sent over a forty-one question spreadsheet on Thursday.', 35, 0, 0, 0.954);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 725186, 747370, 'I have seen it. About thirty of those we can answer from the SOC 2 report and the trust page. Six need engineering. And there are five I would call genuinely hard - pen test summary, data residency, sub-processor list with notice periods, encryption key rotation, and their question about whether we can pin a region for their tenant.', 59, 0, 0, 0.967);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp3', 747793, 749673, 'Can we pin a region?', 5, 0, 0, 0.949);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 750200, 758848, 'Not today. We are single-region in us-east. Multi-region is on the roadmap for Q1 and it is not a small piece of work.', 23, 0, 0, 0.943);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 759183, 761535, 'So what do we tell them?', 6, 0, 0, 0.957);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 760995, 776035, 'The honest answer. We say single-region today, contractual commitment on data location, and a dated roadmap item for regional pinning in Q1. If we fudge it and they find out during the review, we lose the deal and the reference.', 40, 1, 0, 0.931);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp2', 776422, 790710, 'I can have the six engineering answers done in a week. The five hard ones need a written position from you and Dan, not from me - I can draft it but someone has to own the commitment.', 38, 0, 0, 0.947);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 791136, 810344, 'Okay. Decision. Sofia gets two engineers for two weeks on the security pack, Dan owns the written position on the five hard questions, and Marcus tells Dev we will have the full response by the fourteenth of October. Not earlier, because I do not want to promise and miss.', 49, 0, 0, 0.963);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp3', 810894, 816158, 'The fourteenth works. They are not in a rush, they are in a process.', 14, 0, 0, 0.945);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp5', 816486, 833446, 'If we commit two engineers for two weeks, that is roughly forty thousand dollars of cost against a deal that has not signed. I am not objecting, I just want it recorded that we are spending ahead of the signature.', 40, 0, 0, 0.964);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 833954, 843754, 'Recorded. I think it is the right bet. One-eighty ACV with a three-year term and a logistics reference is worth forty grand of engineering time.', 25, 0, 0, 0.986);
