INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp2', 1358497, 1367897, 'The eighteenth. Forty-seven minutes of degraded ingest, full outage for about twenty of those. Roughly eleven hundred customers affected, and three of them were mid-migration.', 25, 0, 0, 0.936);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 1368295, 1376943, 'Root cause was the schema migration going out without the rollback path tested. We had the rollback written. Nobody ran it in staging.', 23, 0, 0, 0.986);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 1377382, 1379734, 'Whose call was it to ship?', 6, 0, 0, 0.969);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 1380283, 1387803, 'Mine. I approved it at four fifty on a Friday because we were trying to make the Monday release window.', 20, 0, 0, 0.948);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 1388210, 1399578, 'Okay. Thank you for saying that plainly. I am not interested in a blame conversation, but I am interested in why a Friday-evening deploy felt like the only option.', 29, 0, 1, 0.977);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 1400169, 1415585, 'Because the release train is weekly and if we miss it we wait seven days. That is the actual pressure. The fix is not ''do not deploy on Friday'', the fix is that missing a train should not cost a week.', 41, 0, 0, 0.987);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp2', 1415999, 1425775, 'Agreed. And separately, on-call was one person for four hours with no escalation path. That is the part that made it forty-seven minutes instead of fifteen.', 26, 0, 0, 0.949);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp6', 1425416, 1439920, 'From my side - we had nine support tickets in the first twenty minutes and no status page update for eleven of them. Customers were finding out from their own dashboards before they found out from us.', 37, 1, 0, 0.945);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp0', 1440206, 1444910, 'That is the worst part, honestly. So: what are we committing to?', 12, 0, 0, 0.961);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp2', 1445367, 1458903, 'Three things. Rollback tested in staging becomes a hard gate, not a checkbox. Second on-call with a fifteen-minute escalation. And status page automation tied to the ingest health check so a human is not the bottleneck.', 36, 0, 0, 0.97);
