INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp6', 1991887, 2000119, 'On the SOC 2 evidence pack, we are a week behind - the staging environment is the thing holding it up.', 21, 0, 0, 0.947);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 2000359, 2010887, 'Two open roles that matter. Staff engineer for the platform team, and a customer success manager for the enterprise book. The staff engineer has been open eleven weeks.', 28, 0, 0, 0.932);
