INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp1', 2017021, 2033189, 'And we have lost three candidates at offer stage on that band in the last two months. The market for staff-level platform engineers with Rust and distributed systems is two thirty-five to two sixty. We are interviewing below market and then being surprised.', 43, 1, 0, 0.948);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-leadership-sync', 'm-leadership-sync-sp5', 2033417, 2045713, 'If we move the band to two sixty, everyone currently at two twenty-five asks for a review. That is the second-order cost and it is bigger than the first.', 29, 0, 0, 0.95);
