INSERT INTO summaries (id, meeting_id, template_key, headline, overview, generated_at, generated_by, tokens_in, tokens_out, latency_ms) VALUES ('m-leadership-sync-standard', 'm-leadership-sync', 'standard', '8 decisions across 61 minutes — September numbers and Halcyon Freight', 'Weekly leadership sync covering September''s close (ARR $4.82m, NRR 112%, gross churn 1.9%), the Halcyon Freight security review blocking a $180k deal, the September 18 outage post-mortem, a comp-band exception for the staff engineer role, and the onboarding v3 results. Marcus left early for a customer call, so sales came before the rest of the agenda. Eight people spoke; the meeting produced eight owned action items and one item explicitly parked.', '2026-09-27T12:00:00Z', 'authored+extractive', 8486, 113, 67);
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-standard', 'overview', 'Overview', 'Weekly Leadership Sync ran 61 minutes with 8 people speaking (Priya, Dan, Sofia, Marcus, Elena, Tom, Aisha, Ben). Topics covered: Roll call & audio check; September numbers; Halcyon Freight — security review; Sept 18 outage post-mortem; Hiring & comp bands; Usage-based pricing (parked); Onboarding revamp; Actions & wrap. 560 transcript segments, 8,486 words. 20 action items were extracted, 17 with a named owner.', 0);
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-standard', 'key_points', 'Key points', '- **[04:12]** September closed at **$4.82m ARR**, up $81k on August, NRR **112%**, gross churn **1.9%** against a plan of 2.2% — *Tom Whitfield*
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-standard', 'decisions', 'Decisions', '- **Halcyon:** two engineers for two weeks on the security pack; Dan owns the written position on the five hard questions; full response promised for **14 October**, deliberately not earlier — *Priya Raman*
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-standard', 'action_items', 'Action items', '- [1:42] **Elena Petrova** — I will keep this quick, I know we are tight on time.
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-standard', 'open_questions', 'Questions raised', '- **[05:20]** Is the Q4 pipeline figure committed or a forecast? — *Priya Raman*
