INSERT INTO summaries (id, meeting_id, template_key, headline, overview, generated_at, generated_by, tokens_in, tokens_out, latency_ms) VALUES ('m-leadership-sync-executive', 'm-leadership-sync', 'executive', 'Exec brief — $4.82m ARR, one $180k deal gated on security, one outage with dated fixes', 'September closed ahead of plan on retention (NRR 112%, churn 1.9% vs 2.2% planned) and behind on new logos (4 vs 9). The largest open item is Halcyon Freight at $180k ACV, gated entirely on a security review rather than price, with $40k of engineering cost being spent ahead of signature. The Sept 18 outage cost 47 minutes and produced four dated process changes. One comp-band exception was approved to unblock an eleven-week-open staff role. Runway is 19 months.', '2026-09-27T12:00:00Z', 'authored+extractive', 8486, 116, 67);
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-executive', 'bottom_line', 'Bottom line', '**Where the business is**
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-executive', 'metrics', 'Numbers mentioned', '- **[0:42]** Aisha said she might be two minutes late, she is finishing a renewal. — *Ben Nakamura*
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-executive', 'risks', 'Risks & exposure', '- **Concentration in one deal.** $340k of the $2.1m Q4 pipeline is Halcyon, unsigned. Reporting it unflagged would move the board number if it slips to November.
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-executive', 'decisions', 'Decisions made', '- **[6:29]** Let us not re-litigate it, we decided this in August. — *Elena Petrova*
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-leadership-sync-executive', 'escalations', 'Needs a decision above this group', '- **Comp band policy.** A one-off exception to $250k was approved. The published band has not moved, which means the next staff-level hire re-opens the same argument. Needs a real decision at Q4 planning with offer data, not another exception.
