INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 8283, 17691, 'The notetaker says it joined. Let me just check the audio is actually coming through, because last time it recorded forty minutes of silence.', 24, 0, 0, 0.95);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 18174, 23270, 'Testing, one two three. The quick brown fox jumps over the lazy dog.', 13, 0, 0, 0.966);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 23831, 37943, 'Um. Right. So the things I want to see when this finishes are - does the transcript have my name on it, does the summary actually say anything, and can I highlight a bit of it.', 36, 0, 1, 0.951);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 38225, 43321, 'I wonder if it will get the names right with only one speaker.', 13, 0, 0, 0.964);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 43724, 48428, 'This is the bit where I would normally be writing something down.', 12, 0, 0, 0.961);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 48675, 53379, 'Let me pause for a second and see if it handles silence.', 12, 0, 0, 0.976);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 53627, 70483, 'Let me say something that would be an action item, so I can see if it picks it up. I need to send the board deck to Tom by Friday, and I should book the offsite venue before the end of the month.', 43, 0, 0, 0.955);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 70732, 77396, 'And a decision, I suppose. We decided to go with the second vendor for the penetration test.', 17, 0, 0, 0.948);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 76681, 82169, 'Okay. That is two minutes. Let us see what comes out the other side.', 14, 1, 0, 0.952);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 82631, 91255, 'If the summary is any good I will stop writing notes in meetings, which would be a genuine quality of life improvement.', 22, 0, 0, 0.968);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 91859, 94995, 'Okay, that sounds like it is picking up.', 8, 0, 1, 0.985);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 95307, 100403, 'Right, so what else do I need to say to make this useful.', 13, 0, 0, 0.956);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-solo-test', 'm-solo-test-sp0', 100624, 104936, 'Let me just keep talking so the transcript is not empty.', 11, 0, 0, 0.952);
