INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp2', 900, 13308, 'Rachel, Dev, thanks for making time. Priya is our CEO and Dan is our CTO, so you have got the two people who can actually answer hard questions rather than me promising things.', 33, 0, 0, 0.947);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp3', 13911, 22935, 'Appreciated. Let me be upfront about where we are - we have evaluated four vendors and you are two. The other one is cheaper.', 24, 0, 0, 0.947);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp0', 23517, 30573, 'That is useful to know early. What is the thing that would make you pick us despite that?', 18, 0, 0, 0.933);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp3', 31074, 43106, 'Honestly, whether your team can survive our security review without a six month detour. We have been burned twice by vendors who said yes to everything and then fell over in procurement.', 32, 0, 0, 0.938);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp2', 43712, 46720, 'Procurement is the bottleneck, not the technical evaluation.', 8, 0, 0, 0.939);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp3', 47247, 52135, 'The honest status on onboarding v3: stalled, with waiting on legal still open.', 13, 0, 0, 0.976);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp0', 52457, 58337, 'The honest status on onboarding v3: a week behind, with the review queue still open.', 15, 0, 0, 0.955);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp3', 58682, 63194, 'They asked about SOC 2 again, which is usually a good sign.', 12, 0, 0, 0.946);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp0', 63423, 67343, 'Can we get a reference customer in the same vertical?', 10, 0, 0, 0.955);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp1', 69451, 74715, 'The deal slipped again. I do not love it but it is still alive.', 14, 0, 0, 0.976);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp1', 75021, 79533, 'I can get them on a call this week if that helps.', 12, 0, 0, 0.938);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp4', 79863, 86903, 'Priya Raman and I talked about the pricing page yesterday and landed on the boring option.', 16, 0, 0, 0.969);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp0', 87388, 93268, 'I would rather ship onboarding v3 late than ship it with unwritten runbooks in it.', 15, 0, 0, 0.956);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp0', 93636, 100692, 'the pricing page is stalled. I would not call it at risk yet, but single-region hosting is real.', 18, 0, 0, 0.934);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp2', 102120, 110392, 'If we do not sort the thin on-call rotation this quarter, the roadmap slips a quarter and takes two things with it.', 22, 0, 0, 0.943);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp2', 110960, 115472, 'They want a pilot, but a paid one, not a free trial.', 12, 0, 0, 0.943);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp4', 115796, 117996, '[people talking over each other]', 5, 0, 0, 0.73);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp4', 118530, 127330, 'Ten days is optimistic for the design system given a dependency on the data team, but it is not impossible.', 20, 0, 0, 0.943);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp4', 127062, 134542, 'time to first value looks fine until you split it by region, and then it does not.', 17, 1, 0, 0.963);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp2', 134775, 140791, 'the Halcyon integration needs a decision, not another conversation - the flag-first rollout is good enough.', 16, 0, 0, 0.965);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp0', 142743, 151759, 'If we do not sort the release train pressure this quarter, we will be explaining it to the board instead of fixing it.', 23, 0, 0, 0.958);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp1', 151348, 156988, 'I will take waiting on legal away and come back with activation attached to it.', 15, 1, 0, 0.956);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-halcyon-discovery', 'm-halcyon-discovery-sp1', 157321, 161457, 'I would rather lose it on price than discount forty percent.', 11, 0, 0, 0.975);
