INSERT INTO summaries (id, meeting_id, template_key, headline, overview, generated_at, generated_by, tokens_in, tokens_out, latency_ms) VALUES ('m-halcyon-discovery-sales', 'm-halcyon-discovery', 'sales', 'Halcyon Freight — $180k ACV, blocked on security not price; pilot proposed', 'Technical discovery with Rachel Kim (VP Data) and Dev Patel (Security Lead) at Halcyon Freight. They have four vendors down to two and the other is ~30% cheaper. The evaluation is being decided by security-review survivability, not feature or price. Northwind''s single-region limitation was disclosed proactively and landed well. Next step is a written security response by 14 October, then a paid four-week pilot against one region of their fleet.', '2026-09-27T12:00:00Z', 'authored+extractive', 3289, 112, 85);
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-halcyon-discovery-sales', 'customer_context', 'Customer context', '- Nine thousand trucks, telemetry arriving in bursts; current pipeline **drops ~2% of data under load** and nobody notices until a customer disputes a delivery window.
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-halcyon-discovery-sales', 'pain_points', 'Pain points', '- **2% data loss at ingest** under burst load — a correctness problem that surfaces as customer disputes, not as an outage.
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-halcyon-discovery-sales', 'objections', 'Objections & how they were handled', '- **"The other one is cheaper"** → Marcus did not dispute it. Reframed against the two engineers Halcyon keeps spending on ingest reliability, and offered a reduced first-quarter rate rather than a discount.
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-halcyon-discovery-sales', 'buying_signals', 'Buying signals', '- Security lead volunteering that a competitor''s documentation contradicted their verbal answer — they are comparing vendors on honesty, which favours disclosure.
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-halcyon-discovery-sales', 'next_steps', 'Next steps', '- [14 Oct] **Dan Okafor** — send the written security position covering the five hard questions, as a document rather than a slide.
INSERT INTO action_items (id, meeting_id, summary_id, text, owner_name, due_text, start_ms, segment_id, done, confidence, created_at) VALUES ('m-halcyon-discovery-sales-ai0', 'm-halcyon-discovery', 'm-halcyon-discovery-sales', 'Send the written security position on region pinning, pen test summary, sub-processors, key rotation and data residency', 'Dan Okafor', '14 October', 599922, NULL, 0, 0.95, '2026-09-27T12:00:00Z');
