INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp0', 900, 3532, 'Standup. Nine minutes, hard stop. Dan first.', 7, 0, 0, 0.957);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp1', 3819, 11339, 'Migration is merged, flag is off. I want to flip it Tuesday, not Monday, because Monday on-call is one person.', 20, 0, 0, 0.966);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp0', 11607, 14615, 'Tuesday. And the rollback is tested this time?', 8, 0, 0, 0.973);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp1', 14850, 17482, 'Ran it in staging yesterday. Fourteen seconds.', 7, 0, 0, 0.952);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp2', 18101, 25853, 'Spec for the alerting cleanup is in review. I need two people to actually read it, not approve it.', 19, 0, 0, 0.934);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp4', 26392, 34872, 'I will read it today. Onboarding is blocked on the empty-state illustrations, which are waiting on the design system tokens.', 20, 0, 0, 0.936);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp5', 34338, 41002, 'Customer side - the Meridian renewal is signed, and two accounts from the outage are still unhappy.', 17, 1, 0, 0.94);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp0', 41418, 45930, 'Okay. Nobody is blocked except Elena, and that is on me. Done.', 12, 0, 0, 0.963);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp5', 45254, 54662, 'the SOC 2 evidence pack is ahead of where I expected. I would not call it at risk yet, but single-region hosting is real.', 24, 1, 0, 0.964);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp1', 55205, 60845, 'It is a two-day change, not two weeks, but the testing is the long part.', 15, 0, 0, 0.961);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp4', 61135, 71735, 'the Halcyon integration is moving again after two dead weeks. I would not call it at risk yet, but the thin on-call rotation is real.', 25, 0, 0, 0.974);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp4', 71990, 80894, 'The run-up to the board meeting is optimistic for the ingest rewrite given the staging environment, but it is not impossible.', 21, 0, 0, 0.981);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-standup', 'm-standup-sp2', 81160, 85648, 'Nobody has reproduced it, which is its own kind of answer.', 11, 0, 1, 0.962);
