INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp0', 900, 10676, 'Yuki, thanks for coming back. This round is system design and then a bit about how you work in incidents. Sofia will drive the design part.', 26, 0, 0, 0.982);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 11123, 14651, 'Great. Should I share a whiteboard or just talk?', 9, 0, 0, 0.935);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 15039, 21055, 'Talk first, draw if it helps. I care more about how you reason than the diagram.', 16, 0, 0, 0.945);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 21630, 32606, 'Understood. For context, the last three years I have been on the streaming side of a logistics platform doing about four hundred thousand events a second at peak.', 28, 0, 0, 0.936);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 33079, 38343, 'I looked at the numbers this morning and gross churn moved barely at all.', 14, 0, 0, 0.966);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 38583, 42719, 'The test suite takes eleven minutes and it is getting worse.', 11, 0, 0, 0.946);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 43203, 49219, 'Can Dan Okafor take the ingest rewrite? It has been sitting without a name on it.', 16, 0, 0, 0.974);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 49822, 54918, 'Latency is down to about 180 milliseconds at p95 on the ingest path.', 13, 0, 0, 0.965);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 55378, 62898, 'Yuki Tanaka and I talked about the SOC 2 evidence pack yesterday and landed on pairing someone senior on it.', 20, 0, 0, 0.959);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 64877, 71149, 'Can Sofia Marchetti take the Halcyon integration? It has been sitting without a name on it.', 16, 0, 0, 0.982);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 71577, 80225, 'If we do not sort a test suite nobody trusts this quarter, the roadmap slips a quarter and takes two things with it.', 23, 0, 0, 0.963);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp0', 80445, 84205, 'The on-call rotation is thin. That is the real risk.', 10, 0, 0, 0.952);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 84641, 90129, 'gross churn is where I would look first to understand how this is going.', 14, 0, 0, 0.973);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 90628, 94940, 'Nobody has reproduced it, which is its own kind of answer.', 11, 0, 1, 0.936);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 96676, 101772, 'We have had three of those alerts this week and two were noise.', 13, 0, 0, 0.975);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp0', 102213, 108605, 'The honest status on onboarding v3: ahead of where I expected, with the migration window still open.', 17, 0, 0, 0.974);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp0', 109053, 116573, 'If Sofia Marchetti agrees, I would start a two-week spike with a hard stop on the pricing page next week.', 20, 0, 0, 0.937);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 117183, 125415, 'On the ingest rewrite, we are ahead of where I expected - the migration window is the thing holding it up.', 21, 0, 0, 0.969);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp0', 125988, 131252, 'That is technical debt we took on deliberately in March and it is due.', 14, 0, 0, 0.957);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 132870, 140710, 'If we do not sort unwritten runbooks this quarter, it stops being an engineering problem and becomes a sales one.', 20, 0, 0, 0.988);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 141051, 147715, 'We can ship it behind a flag and roll back in five minutes if it goes wrong.', 17, 0, 0, 0.965);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 148068, 152772, 'The migration is done, we just have not flipped the flag yet.', 12, 0, 0, 0.935);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 153374, 160142, 'Can Dan Okafor take the SOC 2 evidence pack? It has been sitting without a name on it.', 18, 0, 0, 0.958);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 160562, 165450, 'I would rather not touch that service until the new owner is hired.', 13, 0, 0, 0.983);
