INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 331632, 341784, 'Design question. Multi-tenant ingest, tenants vary by a factor of about two hundred in volume, and one tenant''s burst must not degrade another''s. Where do you start?', 27, 0, 0, 0.94);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 342015, 362791, 'I would start with the noisy-neighbour problem rather than the ingest problem, because ingest is mostly solved. Two approaches - per-tenant queues with weighted fair scheduling, or admission control at the edge with per-tenant token buckets. I would do both, but the token bucket first because it is cheap and it fails safe.', 53, 0, 0, 0.969);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 363196, 365452, 'What does fail safe mean there?', 6, 0, 0, 0.972);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 366062, 377822, 'It means when the system is confused, it sheds the largest tenant first rather than the smallest. Most implementations get that backwards and end up protecting whoever is shouting loudest.', 30, 0, 0, 0.943);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp0', 378138, 383026, 'That is a good answer. What breaks first at ten times the load?', 13, 0, 0, 0.937);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 383602, 401242, 'Metadata, not data. Everyone plans for the bytes and nobody plans for the key space. Tenant count times partition count times retention is usually what falls over, and it falls over as a slow death rather than an outage, which makes it harder to catch.', 45, 0, 0, 0.98);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 401670, 403550, 'How would you catch it?', 5, 0, 0, 0.948);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 403834, 414810, 'A synthetic load test that grows tenant count rather than throughput. Almost nobody runs that because it is boring and it does not look impressive on a slide.', 28, 0, 0, 0.982);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp0', 415375, 421391, 'Somebody should write down what we mean by plan tier, because we all mean something different.', 16, 0, 0, 0.971);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 421698, 422348, '[crosstalk]', 1, 0, 0, 0.745);
