INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 1164333, 1181189, 'Last March. We lost a region for about two hours. The technical fix took twenty minutes. The other hundred minutes were us arguing about whether to fail over, because nobody had authority to make the call and the person who did was unreachable.', 43, 0, 0, 0.936);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp0', 1181514, 1183394, 'What did you change afterwards?', 5, 0, 0, 0.985);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 1182840, 1204400, 'Two things. We wrote down explicitly who can declare a failover, and it is the on-call engineer, not a VP. And we made the failover a rehearsed monthly event so that declaring it is boring. The second one mattered more. People do not take an action in a crisis that they have never taken before.', 55, 1, 0, 0.981);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp1', 1204848, 1208608, 'Did anyone push back on giving that authority to on-call?', 10, 0, 0, 0.951);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-interview', 'm-interview-sp2', 1209104, 1222432, 'Enormously. Two directors were genuinely uncomfortable. What settled it was that on-call made a bad call in a rehearsal in month two and it cost us nothing, which proved the blast radius was survivable.', 34, 0, 0, 0.985);
