INSERT INTO summaries (id, meeting_id, template_key, headline, overview, generated_at, generated_by, tokens_in, tokens_out, latency_ms) VALUES ('m-interview-standard', 'm-interview', 'standard', 'Strong hire on system design and incident judgement; the comp band is the only blocker', 'Round three for the staff platform engineer role, then a debrief once the candidate left. Yuki Tanaka''s metadata-scaling answer and her incident story - authority moved to on-call, then proven survivable in rehearsal - read as staff-level to both interviewers independently. The open risk is compensation: $265k named against a $200-225k band, with a competing offer, and a decision that cannot wait for the next leadership sync.', '2026-09-27T12:00:00Z', 'authored+extractive', 5914, 107, 76);
