INSERT INTO summaries (id, meeting_id, template_key, headline, overview, generated_at, generated_by, tokens_in, tokens_out, latency_ms) VALUES ('m-design-review-standard', 'm-design-review', 'standard', 'Onboarding v3 lifts activation 31% to 38% self-serve; the sample-data question goes to a two-week test', 'Walkthrough of onboarding v3 with the beta numbers corrected in the room: 44% including two hand-held accounts, 38% self-serve, and Elena insisted on showing the lower figure. The one unresolved argument - sample data in the empty state - was settled the right way, with a two-week A/B test and a kill criterion written down before anyone could re-argue it.', '2026-09-27T12:00:00Z', 'authored+extractive', 4778, 89, 49);
INSERT INTO summary_sections (summary_id, section_key, title, body, sort_order) VALUES ('m-design-review-standard', 'overview', 'Overview', 'Design review — onboarding v3 ran 35 minutes with 5 people speaking (Elena, Priya, Ben, Sofia, Aisha). Topics covered: Walkthrough; The empty state argument. 323 transcript segments, 4,778 words. 13 action items were extracted, 12 with a named owner.', 0);
