INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp0', 900, 12268, 'Welcome to the September all-hands. Three things today - where the business is, an honest conversation about the outage on the eighteenth, and then questions with nothing off limits.', 29, 0, 0, 0.948);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp2', 11825, 22849, 'Numbers first. We closed September at four point eight two million ARR. We added six customers, four of which were new logos and two were expansions.', 26, 1, 0, 0.948);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp0', 23257, 40113, 'And I want to be straight with everyone - four new logos against a target of nine is not where we want to be. We are not changing the target mid-quarter, but we are going to talk hard about it in Q4 planning.', 43, 0, 0, 0.938);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp4', 40672, 53456, 'For context from the sales side, pipeline is healthy at two point one million. The problem is conversion speed, not interest. Deals are taking about fourteen days longer than they did in the spring.', 34, 0, 0, 0.935);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp4', 53922, 59562, 'I will take the migration window away and come back with activation attached to it.', 15, 0, 0, 0.931);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp2', 60159, 64399, 'I think we are agreeing with each other here, actually.', 10, 0, 0, 0.932);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp0', 64751, 71023, 'Quick flag - Marcus Lee is out next week, so anything needing them has to move.', 16, 0, 0, 0.948);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp0', 71628, 76332, 'Do we have a number for that, or is it a feeling?', 12, 0, 0, 0.981);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp1', 76591, 81103, 'Hang on, I am still in another call, give me ten seconds.', 12, 0, 0, 0.989);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp3', 82762, 89154, 'I would rather ship onboarding v3 late than ship it with the thin on-call rotation in it.', 17, 0, 0, 0.976);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp2', 89480, 96264, 'I will take waiting on legal away and come back with gross churn attached to it.', 16, 0, 0, 0.958);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp5', 96574, 102454, 'That is the third time this has come up this month, which tells me something.', 15, 0, 0, 0.936);
