INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp2', 119431, 128335, 'I am less worried about the release train pressure than about a dependency on the data team, if I am honest.', 21, 0, 0, 0.95);
