INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp5', 234405, 240285, 'I looked at the numbers this morning and support ticket volume moved barely at all.', 15, 0, 0, 0.973);
