INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp0', 632958, 645894, 'The eighteenth. Forty-seven minutes of degraded ingest. About eleven hundred customers were affected. I want to explain what happened and what we are changing, and I want to do it without blaming anyone.', 33, 0, 0, 0.94);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp1', 646462, 662630, 'A schema migration went out without the rollback path being tested in staging. The rollback existed. Nobody ran it. I approved the deploy on a Friday evening because we were chasing the Monday release window, and that is the part I would change.', 43, 0, 0, 0.984);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp3', 662059, 673715, 'The reason it lasted forty-seven minutes rather than fifteen is that on-call was a single person with no escalation path. That is a staffing and process failure, not an individual one.', 31, 1, 0, 0.931);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp0', 674329, 691185, 'So the changes are - rollback testing becomes a hard gate in the pipeline, second on-call with fifteen minute escalation, automated status page updates, and we are moving to two release trains a week so that missing one does not cost seven days.', 43, 0, 0, 0.933);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-allhands', 'm-allhands-sp1', 691663, 699935, 'And the Friday-evening pressure disappears once the train runs twice a week. That is the actual root cause, more than the migration.', 22, 0, 0, 0.936);
