INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-investor', 'm-investor-sp0', 900, 10700, 'Nina, thanks for the time. Quick version - ARR four point eight two, net revenue retention a hundred and twelve, gross churn one point nine.', 25, 0, 0, 0.961);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-investor', 'm-investor-sp2', 10923, 15819, 'Those are good. What is the number you are least happy about?', 12, 0, 0, 0.989);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-investor', 'm-investor-sp0', 15172, 20268, 'New logos. Four against a target of nine. That is the honest answer.', 13, 1, 0, 0.955);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-investor', 'm-investor-sp2', 20554, 25858, 'Thank you for leading with that. Is it demand or is it conversion?', 13, 0, 0, 0.952);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-investor', 'm-investor-sp3', 26362, 36514, 'Conversion. Pipeline is two point one million, which is above plan. Deals are taking about fourteen days longer to close than in the spring, mostly in procurement.', 27, 0, 0, 0.953);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-investor', 'm-investor-sp2', 37036, 45604, 'That is a common pattern at your stage. It usually means you are moving upmarket without having changed how you sell.', 21, 0, 0, 0.959);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-investor', 'm-investor-sp3', 46018, 49778, 'Can we get a reference customer in the same vertical?', 10, 0, 0, 0.96);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-investor', 'm-investor-sp2', 50194, 53458, 'Procurement is the bottleneck, not the technical evaluation.', 8, 0, 0, 0.979);
INSERT INTO segments (meeting_id, speaker_id, start_ms, end_ms, text, words, is_crosstalk, is_filler, confidence) VALUES ('m-investor', 'm-investor-sp1', 53936, 60720, 'qualified pipeline looks fine until you split it by customer size, and then it does not.', 16, 0, 0, 0.941);
