INSERT INTO summaries (id, meeting_id, template_key, headline, overview, generated_at, generated_by, tokens_in, tokens_out, latency_ms) VALUES ('m-investor-standard', 'm-investor', 'standard', 'Q3 update to Brightpath: strong retention, four new logos against nine, and a straight answer on the outage', 'Priya and Tom with Nina Alvarez from Brightpath. The good numbers led but so did the bad one - four new logos against a target of nine - and Nina''s two concerns (runway assumptions and the outage) were answered with the full post-mortem and dated changes rather than a summary of it. No raise planned for Q1; the intention is to raise from strength in the second half.', '2026-09-27T12:00:00Z', 'authored+extractive', 2432, 92, 67);
